<?php
require_once __DIR__.'/../../config/cors.php';require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../helpers/response.php';require_once __DIR__.'/../../middleware/auth.php';require_once __DIR__.'/../../helpers/crm_api.php';
$actor=requireAuth($pdo);if($_SERVER['REQUEST_METHOD']!=='PUT')sendError('Method not allowed.',405);requireCsrfToken();$id=crmId($_GET['id']??null,'Booking ID',true);$body=crmJsonBody();$driverId=crmId($body['driverId']??null,'Driver ID',false);$vehicleId=crmId($body['vehicleId']??null,'Vehicle ID',false);crmAssertOwned($pdo,'bookings',$id,$actor);if($driverId){$s=$pdo->prepare("SELECT id FROM drivers WHERE id=:id AND status='active'");$s->execute(['id'=>$driverId]);if(!$s->fetchColumn())sendError('Driver not found or inactive.',422);}if($vehicleId){$s=$pdo->prepare("SELECT id FROM vehicles WHERE id=:id AND status='active'");$s->execute(['id'=>$vehicleId]);if(!$s->fetchColumn())sendError('Vehicle not found or inactive.',422);}if($driverId&&$vehicleId){$s=$pdo->prepare('UPDATE vehicles SET driver_id=:driver WHERE id=:vehicle');$s->execute(['driver'=>$driverId,'vehicle'=>$vehicleId]);}$s=$pdo->prepare('UPDATE bookings SET driver_id=:driver,vehicle_id=:vehicle,driver_vehicle_details=:details WHERE id=:id');$s->execute(['driver'=>$driverId,'vehicle'=>$vehicleId,'details'=>trim((string)($body['driverVehicleDetails']??'')),'id'=>$id]);sendResponse(['success'=>true,'data'=>['bookingId'=>(string)$id,'driverId'=>$driverId?(string)$driverId:null,'vehicleId'=>$vehicleId?(string)$vehicleId:null]]);
